    fn panel_height(&self, phone: bool) -> f32 {
        let mut height = 449.;
        if phone {
            height += 18.;
        }
        if self.access.is_empty() {
            height -= 52.;
        }
        if self.channels.is_empty() {
            height -= 52.;
        }
        if self.people.is_empty() {
            height -= 93.;
        }
        if self.access_open {
            height += self.access.len() as f32 * 55. + 1.;
        }
        if self.send_error.is_some() {
            height += 24.;
        }
        height
    }
}

impl Render for ShareSheet {
    fn render(&mut self, w: &mut Window, cx: &mut Context<Self>) -> impl IntoElement {
        let viewport = w.viewport_size();
        let phone = self.sheet_on_phones && viewport.width <= px(520.);
        let paint = Paint::get(cx);
        let radius = surface_radius(cx);
        let title = self
            .label
            .clone()
            .unwrap_or_else(|| tr(cx, "Share", "分享").into());
        let trigger_width = (measure(&title, 14., w) + 55.)
            .ceil()
            .min((f32::from(viewport.width) - 16.).max(1.));
        let available = (f32::from(viewport.width) - if phone { 16. } else { 32. }).max(1.);
        let panel_width = self.width.min(available);
        let sent_width = SENT_WIDTH.min(available);
        let available_height = (f32::from(viewport.height) - 16.).max(1.);
        let panel_height = self.panel_height(phone).min(available_height);
        let sent_height = (if phone { 206. } else { 192_f32 }).min(available_height);
        let dimensions = |surface| match surface {
            Surface::Trigger => (trigger_width, TRIGGER_HEIGHT),
            Surface::Panel => (panel_width, panel_height),
            Surface::Sent => (sent_width, sent_height),
        };
        let (target_w, target_h) = dimensions(self.surface);
        let open = self.surface != Surface::Trigger;
        let target_corner = if open {
            f32::from(radius)
        } else {
            TRIGGER_HEIGHT / 2.
        };
        for (index, target) in [(0, target_w), (1, target_h), (3, target_corner)] {
            let spring = &mut self.geometry[index];
            if self.initialized {
                spring.duration(target, 0.36, cx);
            } else {
                spring.reset(target);
            }
        }
        self.initialized = true;
        let mut width = self.geometry[0].get(w, cx);
        let mut height = self.geometry[1].get(w, cx);
        let drag = self.geometry[2].get(w, cx);
        let corner = self.geometry[3].get(w, cx);
        let age = self.face_clock.age(cx);
        if age < FACE_SECONDS {
            w.request_animation_frame();
        }
        let mix = ease(age / FACE_SECONDS);
        let reduced = disabled_motion(cx);
        let phone_reveal = if phone {
            self.phone_open
                .duration(if open { 1. } else { 0. }, 0.36, cx);
            if !open || self.leaving == Surface::Trigger {
                (width, height) = dimensions(if open { self.surface } else { self.leaving });
            }
            self.phone_open.get(w, cx).clamp(0., 1.)
        } else {
            self.phone_open.reset(if open { 1. } else { 0. });
            0.
        };
        let animating_closed = !open
            && if phone {
                phone_reveal > 0.001
            } else {
                (width - trigger_width).abs() > 0.05 || age < FACE_SECONDS
            };
        let now = cx.background_executor().now();
        self.flights.retain(|flight| {
            now.saturating_duration_since(flight.started).as_secs_f32() < FLIGHT_SECONDS
        });
        let trigger = face(
            "share-trigger",
            title.clone(),
            TRIGGER_HEIGHT,
            TRIGGER_HEIGHT / 2.,
            Tone::Primary,
            cx,
        )
        .debug_selector(|| "share-trigger".into())
        .track_focus(&self.trigger_focus)
        .tab_stop(!open)
        .aria_expanded(open)
        .w(px(trigger_width))
        .gap(px(8.))
        .opacity(if open && !phone {
            0.
        } else if animating_closed && !phone {
            mix
        } else {
            1.
        })
        .child(share_icon(paint.inverse))
        .child(text_line(title, 14., paint.inverse))
        .on_click(cx.listener(|s, _, w, cx| s.open(w, cx)));
        let root = div()
            .relative()
            .w(px(trigger_width))
            .h(px(TRIGGER_HEIGHT))
            .flex_none();
        let root = match &self.style {
            Some(style) => style(root),
            None => root,
        };
        let mut root = root
            .id(self.id.clone())
            .child(self.trigger_bounds.measure())
            .child(trigger);
        if !open && !animating_closed {
            return root;
        }

        let (left, top) = place(
            self.trigger_bounds.get(),
            viewport,
            size(px(width), px(height)),
            self.align,
            phone,
            px(drag
                + if phone {
                    (1. - phone_reveal) * (height + 8.)
                } else {
                    0.
                }),
        );
        let face_for = |surface, opacity: f32, offset: f32| {
            let (content_w, content_h) = dimensions(surface);
            let face = match surface {
                Surface::Trigger => div(),
                Surface::Panel => self.panel(phone, w, cx),
                Surface::Sent => self.confirmation(paint, cx),
            };
            let grabber = div()
                .relative()
                .id("share-grabber")
                .debug_selector(|| "share-grabber".into())
                .w_full()
                .h(px(14.))
                .flex()
                .items_center()
                .justify_center()
                .cursor_move()
                .child(div().w(px(36.)).h(px(4.)).rounded_full().bg(paint.faint))
                .on_mouse_down(
                    MouseButton::Left,
                    cx.listener(|s, e: &MouseDownEvent, _, _| s.drag_start = Some(e.position.y)),
                )
                .child(
                    self.contact
                        .listen(cx, |s, event, w, cx| match event.phase {
                            TouchPhase::Started => s.drag_start = Some(event.position.y),
                            TouchPhase::Moved => s.move_drag(event.position.y, cx),
                            TouchPhase::Ended => s.end_drag(false, w, cx),
                            TouchPhase::Cancelled => s.end_drag(true, w, cx),
                        }),
                );
            let grabber_height = if phone { 14. } else { 0. };
            let scroll = self.panel_scroll.clone();
            let current = self.surface == surface;
            let region = canvas(
                |_, _, _| (),
                move |bounds, _, _, cx| {
                    if let Some(host) = cx.try_global::<MenuScrollRegion>() {
                        let offset = -scroll.offset().y;
                        let end = scroll.max_offset().y;
                        if end > px(0.1) {
                            (host.0)(bounds, offset > px(0.1), offset < end - px(0.1));
                        }
                    }
                },
            )
            .absolute()
            .top(px(grabber_height))
            .bottom_0()
            .left_0()
            .right_0();
            div()
                .id(("share-face", surface as usize))
                .absolute()
                .top(px(offset))
                .left(px(if phone {
                    (width - content_w) * 0.5
                } else {
                    match self.align {
                        ShareSheetAlign::Start => 0.,
                        ShareSheetAlign::Center => (width - content_w) * 0.5,
                        ShareSheetAlign::End => width - content_w,
                    }
                }))
                .w(px(content_w))
                .h(px(content_h))
                .opacity(opacity)
                .when(phone, |e| e.child(grabber))
                .child(
                    div()
                        .id("share-body")
                        .w_full()
                        .h(px((content_h - grabber_height - 2.).max(1.)))
                        .overflow_y_scroll()
                        .when(current, |e| {
                            e.track_scroll(&self.panel_scroll)
                                .on_scroll(cx.listener(|_, _, _, cx| cx.notify()))
                        })
                        .child(face),
                )
                .when(current, |e| e.child(region))
        };
        let coverage = (width / target_w).min(height / target_h);
        let incoming = if self.leaving == self.surface {
            1.
        } else if !phone && self.leaving == Surface::Trigger && !reduced && age < 0.35 {
            mix.min(ease(((coverage - 0.68) / 0.32).clamp(0., 1.)))
        } else {
            mix
        };
        let shell_color = if phone {
            paint.panel
        } else if !open {
            paint.panel.blend(paint.bright.opacity(mix))
        } else if self.leaving == Surface::Trigger {
            paint.bright.blend(paint.panel.opacity(mix))
        } else {
            paint.panel
        };
        let mut shell = div()
            .id("share-shell")
            .debug_selector(|| "share-shell".into())
            .absolute()
            .left(left)
            .top(top)
            .w(px(width))
            .h(px(height))
            .rounded(if phone { radius } else { px(corner) })
            .bg(shell_color)
            .border_1()
            .border_color(paint.line)
            .shadow(vec![
                BoxShadow::new(
                    px(0.),
                    px(14.),
                    black().opacity(if paint.panel.l < 0.5 { 0.28 } else { 0.14 }),
                )
                .blur_radius(px(30.)),
            ])
            .overflow_hidden()
            .when(open, |e| {
                e.track_focus(&self.scope)
                    .tab_stop(false)
                    .tab_group()
                    .role(Role::Dialog)
                    .aria_label(format!("{} {}", tr(cx, "Share", "分享"), self.title))
                    .block_mouse_except_scroll()
                    .on_key_down(cx.listener(Self::keyboard))
                    .on_mouse_down_out(cx.listener(move |s, _, w, cx| s.close(phone, w, cx)))
            })
            .when_some(
                (self.leaving != Surface::Trigger
                    && (age < FACE_SECONDS || phone && animating_closed))
                    .then_some(self.leaving),
                |e, prior| {
                    e.child(face_for(
                        prior,
                        if phone && !open { 1. } else { 1. - mix },
                        if reduced { 0. } else { -5. * mix },
                    ))
                },
            )
            .when(open, |e| {
                e.child(face_for(
                    self.surface,
                    incoming,
                    if reduced { 0. } else { 5. * (1. - incoming) },
                ))
            });
        if !open && !phone {
            shell = shell.opacity(1. - mix);
        }

        let mut layers = div()
            .w(viewport.width)
            .h(viewport.height)
            .relative()
            .when(phone, |e| {
                e.child(
                    div()
                        .absolute()
                        .inset_0()
                        .bg(black().opacity(0.54 * phone_reveal))
                        .when(open, |e| e.block_mouse_except_scroll()),
                )
            })
            .child(shell)
            .when(phone && open, |e| e.child(self.drag_capture(cx)));
        for flight in &self.flights {
            let saved = &self.people_bounds[flight.person];
            let to = if flight.to_chip {
                saved.chip.get()
            } else {
                saved.recent.get()
            };
            w.request_animation_frame();
            if to.size.width > px(0.) {
                let (at, _) = flight.sample(to, now);
                layers = layers.child(
                    avatar(&self.people[flight.person], at.size.width, paint)
                        .absolute()
                        .left(at.left())
                        .top(at.top()),
                );
            }
        }
        let announcement = self.announce(cx);
        if !announcement.is_empty() {
            root = root.child(
                div()
                    .id("share-status")
                    .role(Role::Status)
                    .aria_label(announcement)
                    .absolute()
                    .size(px(1.))
                    .opacity(0.),
            );
        }
        root.child(
            deferred(anchored().position(point(px(0.), px(0.))).child(layers)).with_priority(4),
        )
    }
}

fn place(
    trigger: Bounds<Pixels>,
    viewport: Size<Pixels>,
    size: Size<Pixels>,
    align: ShareSheetAlign,
    phone: bool,
    drag: Pixels,
) -> (Pixels, Pixels) {
    let center = trigger.center();
    if phone {
        return (
            (viewport.width - size.width) / 2.,
            viewport.height - size.height - px(8.) + drag,
        );
    }
    let x = match align {
        ShareSheetAlign::Start => trigger.left(),
        ShareSheetAlign::End => trigger.right() - size.width,
        ShareSheetAlign::Center => center.x - size.width / 2.,
    };
    (
        x.clamp(px(8.), (viewport.width - size.width - px(8.)).max(px(8.))),
        (center.y - size.height / 2.)
            .clamp(px(8.), (viewport.height - size.height - px(8.)).max(px(8.))),
    )
}

#[cfg(test)]
mod tests {
    use super::{SharePerson, ShareSheet, ShareSheetAccess, ShareSheetAlign, Surface};
    use crate::foundation::Theme;
    use gpui::{
        App, Modifiers, MouseButton, TestAppContext, VisualTestContext, point, prelude::*, px, size,
    };
    use std::{cell::RefCell, rc::Rc, time::Duration};

    fn tick(w: &mut VisualTestContext, millis: u64) {
        w.executor().advance_clock(Duration::from_millis(millis));
        w.update(|w, cx| {
            w.simulate_next_frame(cx);
            w.refresh();
        });
        w.run_until_parked();
    }

    fn click(w: &mut VisualTestContext, selector: &'static str) {
        let bounds = w
            .debug_bounds(selector)
            .unwrap_or_else(|| panic!("missing {selector}"));
        w.simulate_click(bounds.center(), Modifiers::default());
        tick(w, 0);
    }

    fn sheet(cx: &App) -> ShareSheet {
        ShareSheet::new(
            "Roadmap",
            "https://example.com/docs/roadmap",
            vec![
                SharePerson::new("ana", "Ana Ruiz"),
                SharePerson::new("sam", "Sam Lee"),
            ],
            vec![
                ShareSheetAccess::new("private", "Invited only"),
                ShareSheetAccess::new("team", "Workspace"),
                ShareSheetAccess::new("public", "Anyone"),
            ],
            cx,
        )
        .with_default_access("team")
        .with_align(ShareSheetAlign::Center)
        .with_style(|e| e.mt(px(200.)).ml(px(240.)))
    }

    #[test]
    fn access_keys_wrap_and_close_in_order() {
        let mut app = TestAppContext::single();
        app.update(|cx| {
            crate::init(cx);
            Theme::global_mut(cx).reduced_motion = true;
        });
        let (view, w) = app.add_window_view(|_, cx| sheet(cx));
        click(w, "share-trigger");
        w.update(|w, cx| assert!(view.read(cx).copy_focus.is_focused(w)));
        click(w, "share-access-trigger");
        w.simulate_keystrokes("down down");
        tick(w, 0);
        w.update(|w, cx| assert!(view.read(cx).options_focus[0].is_focused(w)));
        w.simulate_keystrokes("enter");
        tick(w, 0);
        w.update(|_, cx| assert_eq!(view.read(cx).access_value().as_ref(), "private"));
        click(w, "share-access-trigger");
        w.simulate_keystrokes("escape");
        tick(w, 0);
        w.update(|w, cx| {
            let share = view.read(cx);
            assert_eq!(share.surface, Surface::Panel);
            assert!(share.access_focus.is_focused(w));
        });
        w.simulate_keystrokes("escape");
        tick(w, 0);
        w.update(|w, cx| {
            let share = view.read(cx);
            assert_eq!(share.surface, Surface::Trigger);
            assert!(share.trigger_focus.is_focused(w));
        });
    }

    #[test]
    fn send_failure_preserves_the_snapshot_and_retry_fires_once() {
        let mut app = TestAppContext::single();
        app.update(|cx| {
            crate::init(cx);
            Theme::global_mut(cx).reduced_motion = true;
        });
        let requests = Rc::new(RefCell::new(Vec::new()));
        let record = requests.clone();
        let (view, w) = app.add_window_view(|_, cx| {
            sheet(cx).on_send(move |request, _, cx| {
                let failed = record.borrow().is_empty();
                record.borrow_mut().push(request);
                let time = cx.background_executor().timer(Duration::from_millis(80));
                cx.spawn(async move |_| {
                    time.await;
                    if failed {
                        Err("Delivery failed".into())
                    } else {
                        Ok(())
                    }
                })
            })
        });
        click(w, "share-trigger");
        click(w, "share-send");
        assert!(requests.borrow().is_empty());
        click(w, "share-person-0");
        click(w, "share-send");
        click(w, "share-send");
        assert_eq!(requests.borrow().len(), 1);
        tick(w, 90);
        w.update(|_, cx| {
            let share = view.read(cx);
            assert_eq!(share.send_error.as_deref(), Some("Delivery failed"));
            assert_eq!(share.selected, vec![0]);
            assert_eq!(share.surface, Surface::Panel);
        });
        click(w, "share-send");
        tick(w, 90);
        let submitted = requests.borrow();
        assert_eq!(submitted.len(), 2);
        assert_eq!(submitted[1].people[0].id.as_ref(), "ana");
        assert_eq!(submitted[1].access.as_ref(), "team");
        w.update(|w, cx| assert!(view.read(cx).done_focus.is_focused(w)));
        click(w, "share-undo");
        w.update(|_, cx| assert_eq!(view.read(cx).selected, vec![0]));
    }

    #[test]
    fn copy_reports_only_the_access_that_was_written() {
        let mut app = TestAppContext::single();
        app.update(|cx| {
            crate::init(cx);
            Theme::global_mut(cx).reduced_motion = true;
        });
        let copied = Rc::new(RefCell::new(Vec::new()));
        let observed = copied.clone();
        let (_, w) = app.add_window_view(|_, cx| {
            sheet(cx).on_copy(move |access, _, _| observed.borrow_mut().push(access))
        });
        click(w, "share-trigger");
        click(w, "share-copy");
        w.update(|_, cx| {
            let clipboard = cx
                .read_from_clipboard()
                .and_then(|contents| contents.text());
            assert_eq!(
                clipboard.as_deref(),
                Some("https://example.com/docs/roadmap")
            );
        });
        assert_eq!(copied.borrow().as_slice(), &["team"]);
    }

    #[test]
    fn mobile_drag_uses_current_offset_and_restores_focus() {
        let mut app = TestAppContext::single();
        app.update(crate::init);
        let (view, w) = app.add_window_view(|_, cx| sheet(cx));
        w.simulate_resize(size(px(320.), px(700.)));
        tick(w, 0);
        click(w, "share-trigger");
        tick(w, 800);
        let bounds = w.debug_bounds("share-shell").unwrap();
        assert_eq!(bounds.size.width, px(304.));
        assert!((bounds.bottom() - px(692.)).abs() < px(0.1));
        for (distance, expected) in [(60., Surface::Panel), (103., Surface::Trigger)] {
            let start = w.debug_bounds("share-grabber").unwrap().center();
            let end = start + point(px(0.), px(distance));
            w.simulate_mouse_move(start, None, Modifiers::default());
            w.simulate_mouse_down(start, MouseButton::Left, Modifiers::default());
            w.simulate_mouse_move(end, MouseButton::Left, Modifiers::default());
            w.simulate_mouse_up(end, MouseButton::Left, Modifiers::default());
            tick(w, 800);
            w.update(|w, cx| {
                let share = view.read(cx);
                assert_eq!(share.surface, expected);
                if expected == Surface::Trigger {
                    assert!(share.trigger_focus.is_focused(w));
                }
            });
        }
    }
}

//! Confirm a clipboard write on the active platform.
use gpui::{App, Task};
#[cfg(target_family = "wasm")]
#[wasm_bindgen::prelude::wasm_bindgen(
    inline_js = "export function kuiCopy(s){return navigator.clipboard ? navigator.clipboard.writeText(s) : Promise.reject(new Error('Clipboard unavailable'))}"
)]
extern "C" {
    #[wasm_bindgen::prelude::wasm_bindgen(js_name=kuiCopy,catch)]
    fn write_web(s: &str) -> Result<js_sys::Promise, wasm_bindgen::JsValue>;
}
pub fn write(text: &str, cx: &mut App) -> Task<bool> {
    #[cfg(not(target_family = "wasm"))]
    {
        cx.write_to_clipboard(gpui::ClipboardItem::new_string(text.to_owned()));
        Task::ready(
            cx.read_from_clipboard()
                .and_then(|v| v.text())
                .is_some_and(|v| v == text),
        )
    }
    #[cfg(target_family = "wasm")]
    {
        let request = write_web(text);
        cx.spawn(async move |_| match request {
            Ok(p) => wasm_bindgen_futures::JsFuture::from(p).await.is_ok(),
            Err(_) => false,
        })
    }
}

//! Focus and activation shared by installed action controls.
use crate::foundation::Theme;
use gpui::{
    App, Context, Div, ElementId, Role, SharedString, Stateful, Window, div, prelude::*, px,
};

pub fn surface(
    id: impl Into<ElementId>,
    label: impl Into<SharedString>,
    cx: &App,
) -> Stateful<Div> {
    let label = label.into();
    let c = &Theme::global(cx).tokens.colors;
    let outline = c.focus_outline;
    div()
        .id(id)
        .role(Role::Button)
        .debug_selector(|| label.to_string())
        .aria_label(label)
        .tab_index(0)
        .min_h(px(44.))
        .px_3()
        .flex()
        .items_center()
        .justify_center()
        .rounded(Theme::global(cx).tokens.radius.md)
        .border_1()
        .border_color(c.border)
        .bg(c.surface)
        .text_color(c.foreground)
        .cursor_pointer()
        .hover(|s| s.opacity(0.8))
        .focus_visible(move |s| {
            s.shadow(vec![gpui::BoxShadow {
                color: outline,
                offset: gpui::point(px(0.), px(0.)),
                blur_radius: px(0.),
                spread_radius: px(2.),
                inset: false,
            }])
        })
}

pub fn activate<T: 'static>(
    el: Stateful<Div>,
    cx: &Context<T>,
    f: impl Fn(&mut T, &mut Window, &mut Context<T>) + Clone + 'static,
) -> Stateful<Div> {
    // GPUI turns a completed Enter/Space press into one keyboard ClickEvent.
    // Registering a second key-down action also toggles on key-up in Web hosts.
    el.on_click(cx.listener(move |v, _, w, cx| f(v, w, cx)))
}

pub fn action<T: 'static>(
    id: impl Into<ElementId>,
    label: impl Into<SharedString>,
    cx: &Context<T>,
    f: impl Fn(&mut T, &mut Window, &mut Context<T>) + Clone + 'static,
) -> Stateful<Div> {
    let label = label.into();
    activate(surface(id, label.clone(), cx).child(label), cx, f)
}

/// Secondary action with a text label and a full keyboard/touch target.
pub fn quiet<T: 'static>(
    id: impl Into<ElementId>,
    label: impl Into<SharedString>,
    cx: &Context<T>,
    f: impl Fn(&mut T, &mut Window, &mut Context<T>) + Clone + 'static,
) -> Stateful<Div> {
    let c = Theme::global(cx).tokens.colors.clone();
    action(id, label, cx, f)
        .border_0()
        .bg(gpui::transparent_black())
        .text_size(px(12.))
        .text_color(c.text_secondary)
}

/// Monochrome control marks drawn with the same paths on both renderers.
#[derive(Clone, Copy)]
pub enum Mark {
    Hold,
    Check,
    Mic,
    Stop,
    Chevron,
    Up,
    Spark,
    Heart,
}
pub fn mark(kind: Mark, ink: gpui::Hsla) -> impl IntoElement {
    use gpui::{PathBuilder, canvas, point};
    canvas(
        |_, _, _| (),
        move |b, _, w, _| {
            let at = |x: f32, y: f32| point(b.origin.x + px(x), b.origin.y + px(y));
            let mut p = PathBuilder::stroke(px(1.55));
            match kind {
                Mark::Hold => {
                    p.move_to(at(3., 10.));
                    p.curve_to(at(8., 2.5), at(2.4, 2.7));
                    p.curve_to(at(13.3, 8.), at(13.2, 2.5));
                    p.move_to(at(4.6, 13.));
                    p.curve_to(at(5.5, 7.5), at(6., 10.5));
                    p.curve_to(at(10.5, 7.5), at(8., 3.5));
                    p.curve_to(at(9.4, 14.), at(11.1, 10.5));
                    p.move_to(at(8., 7.5));
                    p.curve_to(at(7.2, 12.1), at(8.6, 9.2));
                }
                Mark::Check => {
                    p.move_to(at(2.3, 8.1));
                    p.line_to(at(6.5, 12.));
                    p.line_to(at(13.8, 3.6));
                }
                Mark::Mic => {
                    p.move_to(at(5.4, 4.));
                    p.curve_to(at(10.6, 4.), at(8., -0.9));
                    p.line_to(at(10.6, 7.8));
                    p.curve_to(at(5.4, 7.8), at(8., 12.5));
                    p.line_to(at(5.4, 4.));
                    p.move_to(at(2.5, 7.5));
                    p.curve_to(at(13.5, 7.5), at(8., 16.5));
                    p.move_to(at(8., 12.));
                    p.line_to(at(8., 15.));
                    p.move_to(at(5.5, 15.));
                    p.line_to(at(10.5, 15.));
                }
                Mark::Stop => {
                    p = PathBuilder::fill();
                    p.move_to(at(3.5, 3.5));
                    p.line_to(at(12.5, 3.5));
                    p.line_to(at(12.5, 12.5));
                    p.line_to(at(3.5, 12.5));
                    p.close();
                }
                Mark::Up => {
                    p.move_to(at(8., 13.5));
                    p.line_to(at(8., 2.5));
                    p.move_to(at(3.2, 7.5));
                    p.line_to(at(8., 2.5));
                    p.line_to(at(12.8, 7.5));
                }
                Mark::Spark => {
                    p.move_to(at(8., 1.5));
                    p.curve_to(at(14.5, 8.), at(9.2, 6.7));
                    p.curve_to(at(8., 14.5), at(9.2, 9.3));
                    p.curve_to(at(1.5, 8.), at(6.8, 9.3));
                    p.curve_to(at(8., 1.5), at(6.8, 6.7));
                    p.close();
                }
                Mark::Heart => {
                    p.move_to(at(8., 13.8));
                    p.cubic_bezier_to(at(1.8, 5.6), at(5., 11.5), at(1.8, 8.6));
                    p.cubic_bezier_to(at(8., 4.4), at(1.8, 2.), at(5.8, 1.6));
                    p.cubic_bezier_to(at(14.2, 5.6), at(10.2, 1.6), at(14.2, 2.));
                    p.cubic_bezier_to(at(8., 13.8), at(14.2, 8.6), at(11., 11.5));
                    p.close();
                }
                Mark::Chevron => {
                    p.move_to(at(5., 6.5));
                    p.line_to(at(8., 9.5));
                    p.line_to(at(11., 6.5));
                }
            }
            if let Ok(path) = p.build() {
                w.paint_path(path, ink);
            }
        },
    )
    .size(px(16.))
    .flex_none()
}

/// Optional host language for labels owned by action controls; English is the default.
#[derive(Clone, Copy, Default, PartialEq, Eq)]
pub enum UiLanguage {
    #[default]
    English,
    Chinese,
}
impl gpui::Global for UiLanguage {}
impl UiLanguage {
    pub fn current(cx: &App) -> Self {
        cx.try_global::<Self>().copied().unwrap_or_default()
    }
    pub fn text<'a>(self, english: &'a str, chinese: &'a str) -> &'a str {
        match self {
            Self::English => english,
            Self::Chinese => chinese,
        }
    }
}

/// Optional host writing direction; left-to-right is the default. GPUI has no
/// direction property, so controls that place things on an inline axis read
/// this the way the Web reads `getComputedStyle(...).direction`.
#[derive(Clone, Copy, Default, PartialEq, Eq)]
pub enum UiDirection {
    #[default]
    Ltr,
    Rtl,
}
impl gpui::Global for UiDirection {}
impl UiDirection {
    pub fn current(cx: &App) -> Self {
        cx.try_global::<Self>().copied().unwrap_or_default()
    }
    pub fn is_rtl(self) -> bool {
        matches!(self, Self::Rtl)
    }
    /// Reverse the inline step when the reading direction runs the other way.
    pub fn inline_step(self, step: isize) -> isize {
        if self.is_rtl() { -step } else { step }
    }
}

//! Direct contact input for controls that cannot wait for a synthesized tap.
use gpui::{prelude::*, *};
use std::{cell::Cell, rc::Rc};
#[derive(Default, Clone)]
pub(crate) struct Contact(Rc<Cell<bool>>);
impl Contact {
    /// Mount over the gesture target. Only the topmost, hovered hitbox may claim a new contact.
    pub(crate) fn listen<T: 'static>(
        &self,
        cx: &Context<T>,
        handle: impl Fn(&mut T, &TouchDragEvent, &mut Window, &mut Context<T>) + 'static,
    ) -> impl IntoElement {
        let listener = cx.listener(handle);
        let active = self.0.clone();
        canvas(
            |bounds, w, _| w.insert_hitbox(bounds, HitboxBehavior::Normal),
            move |_, hit, w, _| {
                w.on_mouse_event(move |e: &TouchDragEvent, phase, w, cx| {
                    if phase.bubble() {
                        if e.phase == TouchPhase::Started {
                            active.set(hit.is_hovered(w));
                        }
                        if !active.get() {
                            return;
                        }
                        if matches!(e.phase, TouchPhase::Ended | TouchPhase::Cancelled) {
                            active.set(false)
                        }
                        if e.phase == TouchPhase::Started {
                            w.prevent_default();
                        }
                        listener(e, w, cx);
                        cx.stop_propagation();
                    }
                })
            },
        )
        .absolute()
        .inset_0()
    }
}

//! Compact action surfaces scoped to the button family.
use crate::foundation::{AccentPalette, Theme, ThemeMode};
use gpui::{prelude::*, *};
use web_time::Instant;
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub enum Tone {
    #[default]
    Surface,
    Primary,
    Muted,
    Danger,
    Success,
    Clear,
}
#[derive(Clone, Copy)]
pub struct Paint {
    pub stage: Hsla,
    pub panel: Hsla,
    pub tray: Hsla,
    pub hover: Hsla,
    pub ink: Hsla,
    pub secondary: Hsla,
    pub faint: Hsla,
    pub line: Hsla,
    pub bright: Hsla,
    pub(crate) focus: Hsla,
    pub inverse: Hsla,
    pub(crate) neutral_inverse: Hsla,
    accent: AccentPalette,
    pub danger: Hsla,
    pub success: Hsla,
}
impl Paint {
    pub fn get(cx: &App) -> Self {
        Self::for_theme(Theme::global(cx))
    }
    pub(crate) fn for_theme(theme: &Theme) -> Self {
        let mut paint = Self::for_mode(theme.mode);
        let tint = theme.accent.for_mode(theme.mode);
        if tint.is_transparent() {
            return paint;
        }
        paint.accent = theme.accent;
        paint.bright = paint.bright.blend(tint);
        paint.focus = theme.tokens.colors.focus_outline;
        paint.inverse = paint.accent.on_fill(paint.bright, paint.neutral_inverse);
        paint.hover = paint.hover.blend(tint.opacity(0.12));
        paint
    }
    pub(crate) fn primary_hover(self, strength: f32) -> Hsla {
        self.bright.blend(
            self.accent
                .hover_tint(self.bright, self.inverse, strength)
                .opacity(strength),
        )
    }
    pub fn for_mode(mode: ThemeMode) -> Self {
        let dark = mode == ThemeMode::Dark;
        let [
            stage,
            panel,
            tray,
            hover,
            ink,
            secondary,
            faint,
            line,
            bright,
            inverse,
            danger,
        ] = if dark {
            [
                0x242424, 0x191919, 0x303030, 0x353535, 0xf2f2f2, 0xb5b5b5, 0x898989, 0x2b2b2b,
                0xf2f2f2, 0x141414, 0xff746f,
            ]
        } else {
            [
                0xf5f5f5, 0xffffff, 0xffffff, 0xe9e9e9, 0x1a1a1a, 0x575757, 0x747474, 0xe2e2e2,
                0x181818, 0xfafafa, 0xbd302c,
            ]
        };
        Self {
            stage: rgb(stage).into(),
            panel: rgb(panel).into(),
            tray: rgb(tray).into(),
            hover: rgb(hover).into(),
            ink: rgb(ink).into(),
            secondary: rgb(secondary).into(),
            faint: rgb(faint).into(),
            line: rgb(line).into(),
            bright: rgb(bright).into(),
            focus: rgb(bright).into(),
            inverse: rgb(inverse).into(),
            neutral_inverse: rgb(inverse).into(),
            accent: AccentPalette::default(),
            danger: rgb(danger).into(),
            success: rgb(if dark { 0x53d986 } else { 0x008039 }).into(),
        }
    }
    pub fn colors(self, t: Tone) -> (Hsla, Hsla) {
        match t {
            Tone::Primary => (self.bright, self.inverse),
            Tone::Success => (self.panel.blend(self.success.opacity(0.10)), self.ink),
            Tone::Muted => (self.secondary, self.neutral_inverse),
            Tone::Clear => (transparent_black(), self.ink),
            _ => (self.panel, self.ink),
        }
    }
}
pub fn face(
    id: impl Into<ElementId>,
    name: impl Into<SharedString>,
    height: f32,
    r: f32,
    t: Tone,
    cx: &App,
) -> Stateful<Div> {
    let p = Paint::get(cx);
    let (bg, fg) = p.colors(t);
    let name = name.into();
    let ring = Theme::global(cx).tokens.colors.focus_outline;
    div()
        .id(id)
        .debug_selector({
            let name = name.clone();
            move || name.to_string()
        })
        .aria_label(name)
        .role(Role::Button)
        .tab_index(0)
        .h(px(height))
        .flex_none()
        .flex()
        .items_center()
        .justify_center()
        .gap(px(8.))
        .rounded(px(r))
        .bg(bg)
        .text_color(fg)
        .text_size(px(14.))
        .line_height(px(19.6))
        .font_weight(FontWeight::MEDIUM)
        .whitespace_nowrap()
        .cursor_pointer()
        .when(t == Tone::Danger, |e| {
            e.border_1().border_color(p.danger.opacity(0.42))
        })
        .when(t == Tone::Success, |e| {
            e.border_1().border_color(p.success.opacity(0.40))
        })
        .focus_visible(move |s| s.border_1().border_color(ring))
}
/// Analytic critically damped spring. Retargeting preserves instantaneous velocity.
#[derive(Clone, Copy, Debug)]
pub struct Slide {
    from: f32,
    to: f32,
    velocity: f32,
    start: Option<Instant>,
    omega: f32,
}
impl Slide {
    pub fn new(v: f32) -> Self {
        Self {
            from: v,
            to: v,
            velocity: 0.,
            start: None,
            omega: 12.47,
        }
    }
    pub fn snappy(v: f32) -> Self {
        Self {
            omega: 20.14,
            ..Self::new(v)
        }
    }
    /// Re-express the same trajectory in a shifted coordinate system, preserving velocity.
    pub fn translate(&mut self, delta: f32) {
        self.from += delta;
        self.to += delta;
    }
    pub fn reset(&mut self, v: f32) {
        self.from = v;
        self.to = v;
        self.velocity = 0.;
        self.start = None;
    }
    pub fn set(&mut self, v: f32, cx: &App) {
        self.retarget(v, self.omega, cx);
    }
    pub fn duration(&mut self, v: f32, visual_seconds: f32, cx: &App) {
        self.retarget(v, 5.236 / visual_seconds, cx)
    }
    /// Settle a directly manipulated value with the measured release speed (units per second).
    pub(crate) fn release(&mut self, target: f32, velocity: f32, seconds: f32, cx: &App) {
        if disabled_motion(cx) {
            self.reset(target);
            return;
        }
        let now = cx.background_executor().now();
        self.from = self.sample(now).0;
        self.to = target;
        self.velocity = velocity;
        self.omega = 5.236 / seconds;
        self.start = Some(now);
    }
    /// Stagger a first reveal without advancing the value before its slot starts.
    pub(crate) fn delayed(&mut self, target: f32, seconds: f32, delay: f32, cx: &App) {
        if self.to == target {
            return;
        }
        self.duration(target, seconds, cx);
        if let Some(start) = self.start.as_mut() {
            *start += std::time::Duration::from_secs_f32(delay.max(0.));
        }
    }
    fn retarget(&mut self, v: f32, omega: f32, cx: &App) {
        if disabled_motion(cx) {
            self.reset(v);
            return;
        }
        if self.to == v {
            return;
        }
        let now = cx.background_executor().now();
        let (pos, vel, _) = self.sample(now);
        self.from = pos;
        self.velocity = vel;
        self.omega = omega;
        self.to = v;
        self.start = Some(now);
    }
    pub(crate) fn sample(&self, now: Instant) -> (f32, f32, bool) {
        let Some(start) = self.start else {
            return (self.to, 0., false);
        };
        let t = now.saturating_duration_since(start).as_secs_f32();
        let d = self.from - self.to;
        let k = self.velocity + self.omega * d;
        let e = (-self.omega * t).exp();
        let offset = (d + k * t) * e;
        let vel = (self.velocity - self.omega * k * t) * e;
        if offset.abs() < 0.0008 && vel.abs() < 0.012 || t > 1.6 {
            (self.to, 0., false)
        } else {
            (self.to + offset, vel, true)
        }
    }
    /// Sample several springs at one instant and let the caller schedule a single frame.
    pub(crate) fn sample_batch(&self, now: Instant, reduced: bool) -> (f32, bool) {
        if reduced {
            (self.to, false)
        } else {
            let (value, _, active) = self.sample(now);
            (value, active)
        }
    }
    /// Sample from an input handler without scheduling a frame outside paint.
    pub fn value(&self, cx: &App) -> f32 {
        if disabled_motion(cx) {
            self.to
        } else {
            self.sample(cx.background_executor().now()).0
        }
    }
    pub fn get(&self, w: &Window, cx: &App) -> f32 {
        if disabled_motion(cx) {
            return self.to;
        }
        let (v, _, m) = self.sample(cx.background_executor().now());
        if m {
            w.request_animation_frame()
        }
        v
    }
}
pub fn disabled_motion(cx: &App) -> bool {
    cx.try_global::<Theme>().is_some_and(|t| t.reduced_motion)
}
/// A finite paint clock; never schedules frames once its last phase has finished.
#[derive(Clone, Copy, Default, Debug)]
pub struct PhaseClock(Option<Instant>);
impl PhaseClock {
    pub fn restart(&mut self, cx: &App) {
        self.0 = Some(cx.background_executor().now())
    }
    pub fn age(self, cx: &App) -> f32 {
        self.0.map_or(f32::INFINITY, |s| {
            cx.background_executor()
                .now()
                .saturating_duration_since(s)
                .as_secs_f32()
        })
    }
    pub fn time(self, end: f32, w: &Window, cx: &App) -> f32 {
        if disabled_motion(cx) {
            return end;
        }
        let t = self.age(cx);
        if t < end {
            w.request_animation_frame()
        }
        t.min(end)
    }
}
pub fn ease(t: f32) -> f32 {
    cubic_out(t, 0.16, 0.30)
}
/// Cubic-bezier(.22, 1, .36, 1) used by page-scale wipes.
pub fn standard_ease(x: f32) -> f32 {
    cubic_out(x, 0.22, 0.36)
}
fn cubic_out(x: f32, x1: f32, x2: f32) -> f32 {
    if x <= 0. || x >= 1. {
        return x.clamp(0., 1.);
    }
    let (mut lo, mut hi) = (0., 1.);
    for _ in 0..14 {
        let t = (lo + hi) * 0.5;
        let v = 1. - t;
        let at = 3. * x1 * v * v * t + 3. * x2 * v * t * t + t * t * t;
        if at < x { lo = t } else { hi = t }
    }
    1. - (1. - (lo + hi) * 0.5_f32).powi(3)
}
pub fn measure(text: &SharedString, size: f32, w: &Window) -> f32 {
    let mut style = w.text_style();
    style.font_weight = FontWeight::MEDIUM;
    let advance: f32 = w
        .text_system()
        .shape_line(text.clone(), px(size), &[style.to_run(text.len())], None)
        .width
        .into();
    (advance - 0.01 * size * text.chars().count() as f32).max(0.)
}
/// Pointer feedback lives in the element's stable hit box, independent of its paint.
pub fn press<T: 'static>(
    el: Stateful<Div>,
    cx: &Context<T>,
    field: fn(&mut T) -> &mut Slide,
) -> Stateful<Div> {
    el.on_mouse_down(
        MouseButton::Left,
        cx.listener(move |v, _, _, cx| {
            field(v).set(1., cx);
            cx.notify()
        }),
    )
    .on_mouse_up(
        MouseButton::Left,
        cx.listener(move |v, _, _, cx| {
            field(v).set(0., cx);
            cx.notify()
        }),
    )
    .on_mouse_up_out(
        MouseButton::Left,
        cx.listener(move |v, _, _, cx| {
            field(v).set(0., cx);
            cx.notify()
        }),
    )
    .on_key_down(cx.listener(move |v, e: &KeyDownEvent, _, cx| {
        if matches!(e.keystroke.key.as_str(), "enter" | "space") {
            field(v).set(1., cx);
            cx.notify()
        }
    }))
    .on_key_up(cx.listener(move |v, e: &KeyUpEvent, _, cx| {
        if matches!(e.keystroke.key.as_str(), "enter" | "space") {
            field(v).set(0., cx);
            cx.notify()
        }
    }))
}

/// Stable glyph identities are matched in reading order, including common suffixes.
fn shared_glyphs(
    left: &[(SharedString, f32)],
    right: &[(SharedString, f32)],
) -> Vec<Option<usize>> {
    let stride = right.len() + 1;
    let mut lcs = vec![0u16; (left.len() + 1) * stride];
    for i in (0..left.len()).rev() {
        for j in (0..right.len()).rev() {
            lcs[i * stride + j] = if left[i].0 == right[j].0 {
                1 + lcs[(i + 1) * stride + j + 1]
            } else {
                lcs[(i + 1) * stride + j].max(lcs[i * stride + j + 1])
            };
        }
    }
    let mut out = vec![None; left.len()];
    let (mut i, mut j) = (0, 0);
    while i < left.len() && j < right.len() {
        if left[i].0 == right[j].0 {
            out[i] = Some(j);
            i += 1;
            j += 1
        } else if lcs[(i + 1) * stride + j] >= lcs[i * stride + j + 1] {
            i += 1
        } else {
            j += 1
        }
    }
    out
}
/// Paint two label phases in one measured slot; the outgoing face never affects layout.
pub fn lettering(
    old: SharedString,
    new: SharedString,
    time: f32,
    letters: bool,
    size: f32,
    ink: Hsla,
    width: f32,
) -> impl IntoElement {
    canvas(
        |_, _, _| (),
        move |b, _, w, cx| {
            let plain = old == new || time >= 0.48;
            let mut style = w.text_style();
            style.font_weight = FontWeight::MEDIUM;
            let width_of = |s: &SharedString| {
                f32::from(
                    w.text_system()
                        .shape_line(s.clone(), px(size), &[style.to_run(s.len())], None)
                        .width,
                )
            };
            let old_x = (width - width_of(&old)) * 0.5;
            let new_x = (width - width_of(&new)) * 0.5;
            if plain {
                let mut run = style.to_run(new.len());
                run.color = ink;
                let line = w
                    .text_system()
                    .shape_line(new.clone(), px(size), &[run], None);
                let _ = line.paint(
                    b.origin + point(px(new_x), px(0.)),
                    b.size.height,
                    TextAlign::Left,
                    None,
                    w,
                    cx,
                );
                return;
            }
            let pieces = |s: &SharedString| -> Vec<(SharedString, f32)> {
                let line =
                    w.text_system()
                        .shape_line(s.clone(), px(size), &[style.to_run(s.len())], None);
                s.char_indices()
                    .map(|(i, c)| (c.to_string().into(), line.x_for_index(i).into()))
                    .collect()
            };
            let mut runs = Vec::new();
            if letters && old.len() < 256 && new.len() < 256 {
                let left = pieces(&old);
                let right = pieces(&new);
                let pairs = shared_glyphs(&left, &right);
                let mut stable = vec![false; right.len()];
                let out = 1. - standard_ease(time / 0.16);
                let layout = 1. - (1. + 12.47 * time) * (-12.47 * time).exp();
                for ((glyph, dx), matched) in left.into_iter().zip(pairs) {
                    if let Some(j) = matched {
                        let x = old_x + dx;
                        stable[j] = true;
                        runs.push((glyph, x + (new_x + right[j].1 - x) * layout, 0., 1., 0.));
                    } else {
                        runs.push((glyph, old_x + dx, -3. * (1. - out), out, 2. * (1. - out)));
                    }
                }
                let mut order = 0;
                for ((glyph, dx), matched) in right.into_iter().zip(stable) {
                    if !matched {
                        let k = ease((time - (order as f32 * 0.016).min(0.1)) / 0.24);
                        runs.push((glyph, new_x + dx, 4. * (1. - k), k, 2. * (1. - k)));
                        order += 1;
                    }
                }
            } else {
                let incoming = ease(time / 0.16);
                runs.push((old.clone(), old_x, 0., 1. - standard_ease(time / 0.10), 0.));
                runs.push((new.clone(), new_x, 2. * (1. - incoming), incoming, 0.));
            }
            for (s, x, y, alpha, blur) in runs {
                if alpha < 0.001 || s.is_empty() {
                    continue;
                }
                let taps = if blur > 0.22 { 5 } else { 1 };
                let mut run = style.to_run(s.len());
                run.color = ink.opacity(alpha / if taps == 5 { 4.3 } else { 1. });
                let line = w.text_system().shape_line(s, px(size), &[run], None);
                for (dx, dy) in [(0., 0.), (-0.7, 0.), (0.7, 0.), (0., -0.7), (0., 0.7)]
                    .into_iter()
                    .take(taps)
                {
                    let _ = line.paint(
                        b.origin + point(px(x + dx * blur), px(y + dy * blur)),
                        b.size.height,
                        TextAlign::Left,
                        None,
                        w,
                        cx,
                    );
                }
            }
        },
    )
    .w(px(width.max(0.)))
    .h(px(size * 1.4))
    .flex_none()
}

#[cfg(test)]
mod spring_tests {
    use super::{Instant, Slide};
    use std::time::Duration;
    #[test]
    fn reversing_keeps_position_and_velocity() {
        let s = Instant::now();
        let mid = s + Duration::from_millis(75);
        let a = Slide {
            start: Some(s),
            to: 1.,
            ..Slide::new(0.)
        };
        let (x, v, _) = a.sample(mid);
        let reversed = Slide {
            start: Some(mid),
            from: x,
            velocity: v,
            to: 0.,
            ..a
        };
        assert_eq!(reversed.sample(mid), (x, v, true));
        assert_eq!(reversed.sample_batch(mid, false), (x, true));
        assert_eq!(reversed.sample_batch(mid, true), (0., false));
        assert!(reversed.sample(mid + Duration::from_millis(240)).0 < x);
        assert_eq!(
            reversed.sample(mid + Duration::from_secs(2)),
            (0., 0., false)
        );
    }
    #[test]
    fn unchanged_suffix_keeps_its_identity_across_label_swaps() {
        let glyphs = |s: &str| {
            s.chars()
                .map(|g| (gpui::SharedString::from(g.to_string()), 0.))
                .collect::<Vec<_>>()
        };
        let old = glyphs("Add to library");
        let new = glyphs("In library");
        let pairs = super::shared_glyphs(&old, &new);
        assert_eq!(
            &pairs[old.len() - 7..],
            &[
                Some(3),
                Some(4),
                Some(5),
                Some(6),
                Some(7),
                Some(8),
                Some(9)
            ]
        );
        assert_eq!(
            super::shared_glyphs(&glyphs("添加成员"), &glyphs("移除成员")),
            vec![None, None, Some(2), Some(3)]
        );
    }
}

#[cfg(test)]
mod accent_tests {
    use super::{AccentPalette, Paint, Theme, ThemeMode};
    use gpui::{Hsla, rgb};
    #[test]
    fn custom_accent_preserves_fill_and_picks_readable_ink_in_both_modes() {
        // Color pairs include near-threshold grays and hues with high/low relative
        // luminance despite identical HSL lightness (yellow and blue).
        for (hex, expected) in [
            (0xffffff, Hsla::black()),
            (0x000000, Hsla::white()),
            (0xffff00, Hsla::black()),
            (0x0000ff, Hsla::white()),
            (0x757575, Hsla::white()),
            (0x767676, Hsla::black()),
            (0xdfa4ef, Hsla::black()),
            (0x221144, Hsla::white()),
        ] {
            let fill: Hsla = rgb(hex).into();
            let accent = AccentPalette {
                light: fill,
                dark: fill,
            };
            let mut theme = Theme::default();
            theme.set_accent(accent);
            for mode in [ThemeMode::Light, ThemeMode::Dark] {
                theme.set_mode(mode);
                let colors = &theme.tokens.colors;
                let p = Paint::for_theme(&theme);
                assert_eq!(colors.accent, fill);
                assert_eq!(p.bright, fill);
                assert_eq!(colors.accent_foreground, expected, "#{hex:06x}");
                assert_eq!(p.inverse, expected);
                assert!(AccentPalette::contrast(p.inverse, p.bright) >= 4.5);
                assert!(AccentPalette::contrast(p.inverse, p.primary_hover(0.12)) >= 4.5);
                assert!(AccentPalette::contrast(colors.focus_outline, colors.surface_muted) >= 3.5);
                assert!(AccentPalette::contrast(colors.focus_outline, p.stage) >= 3.);
                // A tint applies to the primary fill, never to text on neutral/status surfaces.
                assert_eq!(p.neutral_inverse, Paint::for_mode(mode).inverse);
            }
        }
    }

    #[test]
    fn theme_presets_keep_their_authored_inks_and_focus_colors() {
        for (light, dark) in [
            (0x245bc4, 0x8bb4ff),
            (0x7142b6, 0xbc9cff),
            (0x08776d, 0x68d4c4),
            (0xb93c67, 0xff94b3),
            (0x955a08, 0xf4be69),
        ] {
            let mut theme = Theme::default();
            let pair = AccentPalette {
                light: rgb(light).into(),
                dark: rgb(dark).into(),
            };
            theme.set_accent(pair);
            for mode in [ThemeMode::Light, ThemeMode::Dark] {
                theme.set_mode(mode);
                let p = Paint::for_theme(&theme);
                let neutral = Paint::for_mode(mode);
                assert_eq!(p.bright, pair.for_mode(mode));
                assert_eq!(p.inverse, neutral.inverse);
                assert_eq!(theme.tokens.colors.focus_outline, pair.for_mode(mode));
            }
            theme.set_accent(AccentPalette::default());
            let p = Paint::for_theme(&theme);
            let neutral = Paint::for_mode(theme.mode);
            assert_eq!(p.bright, neutral.bright);
            assert_eq!(p.inverse, neutral.inverse);
        }
    }
}

//! Window-relative placement for transient surfaces.
use gpui::{prelude::*, *};
use std::{cell::Cell, rc::Rc};

#[derive(Default, Clone)]
pub(crate) struct TriggerBounds(Rc<Cell<Bounds<Pixels>>>);
impl TriggerBounds {
    pub fn measure(&self) -> impl IntoElement {
        let saved = self.0.clone();
        canvas(move |b, _, _| saved.set(b), |_, _, _, _| ())
            .absolute()
            .inset_0()
    }
    pub fn get(&self) -> Bounds<Pixels> {
        self.0.get()
    }
    /// Prefer below the trigger. Flip above when it leaves more room.
    pub fn place(
        &self,
        view: Size<Pixels>,
        height: Pixels,
        gap: Pixels,
    ) -> (Point<Pixels>, Anchor) {
        let b = self.get();
        if b.bottom() + gap + height > view.height - px(10.) && b.top() > view.height - b.bottom() {
            (point(b.left(), b.top() - gap), Anchor::BottomLeft)
        } else {
            (point(b.left(), b.bottom() + gap), Anchor::TopLeft)
        }
    }
}

